 }
 * { box-sizing: border-box; }
 body {
 margin: 0;
 font-family: "IBM Plex Sans", system-ui, sans-serif;
 background: var(--bg);
 color: var(--text);
 line-height: 1.5;
 }
 header {
 padding: 1.25rem 1.5rem;
 border-bottom: 1px solid var(--border);
 background: linear-gradient(180deg, #152033, var(--bg));
 }
 header .kicker { color: var(--accent); font-size: .75rem; letter-spacing: .08em; text-transform: uppercase; margin: 0 0 .35rem; }
 h1 { margin: 0 0 .25rem; font-size: 1.45rem; font-weight: 600; }
 .subtitle { color: var(--muted); font-size: .92rem; max-width: 46rem; }
 main { padding: 1.5rem; max-width: 1180px; margin: 0 auto; }
 .target {
 display: flex; flex-wrap: wrap; gap: .65rem; align-items: center;
 background: var(--panel); border: 1px solid var(--border); border-radius: 10px;
 padding: .9rem 1rem; margin-bottom: 1.25rem;
 }
 .target label { font-size: .72rem; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
 .target code {
