 padding: .45rem .8rem; font-weight: 600; cursor: pointer; text-decoration: none;
 font-size: .85rem; display: inline-block;
 }
 button.ghost, a.ghost { background: #2d3a4f; color: var(--text); }
 button:hover, .btn:hover { filter: brightness(1.08); }
 .grid { display: grid; grid-template-columns: 1.15fr .85fr; gap: 1rem; }
 @media (max-width: 900px) { .grid { grid-template-columns: 1fr; } }
 section {
 background: var(--panel); border: 1px solid var(--border); border-radius: 10px;
 padding: 1rem 1.1rem; margin: 0;
 }
