247	type ConnAuth = NonNullable<Awaited<ReturnType<typeof getConnectionAuth>>>;
248	
249	async function ensureAccessToken(auth: ConnAuth): Promise<string> {
250	  const { conn, client, token } = auth;
251	  if (token.expiresAt.getTime() > Date.now()) return decrypt(token.accessTokenEnc);
252	
253	  const refresh = token.refreshTokenEnc ? decrypt(token.refreshTokenEnc) : null;
254	  if (!refresh) return decrypt(token.accessTokenEnc);
255	
256	  const next = await doRefresh({
257	    tokenEndpoint: conn.tokenEndpoint,
258	    refreshToken: refresh,
259	    resource: conn.resourceUrl,
260	    client,
261	  });
262	  await saveRefreshedTokens(conn.id, next);
263	  return next.accessToken;
264	}
