266	async function withClient<T>(
267	  conn: McpConnection,
268	  accessToken: string,
269	  fn: (client: Client) => Promise<T>,
270	): Promise<T> {
271	  const transport = new StreamableHTTPClientTransport(new URL(conn.resourceUrl), {
272	    requestInit: { headers: { Authorization: `Bearer ${accessToken}` } },
273	  });
274	  const client = new Client(
275	    { name: "integratrip", version: "1.0.0" },
276	    { capabilities: {} },
277	  );
278	  try {
279	    await client.connect(transport);
280	    return await fn(client);
281	  } finally {
282	    await client.close().catch(() => {});
283	  }
284	}
