460	import { cookies } from "next/headers";
461	import { hmac, safeEqual } from "@/lib/crypto";
462	import { cryptoEnv } from "@/config/env";
463	
464	// Signed (HMAC) session cookie carrying only the user's identity. Tokens and
465	// secrets never go in the cookie — they live encrypted in the database.
466	
467	const COOKIE = "it_session";
468	const MAX_AGE = 60 * 60 * 24 * 7;
469	
470	export type Session = {
471	  uid: string;
472	  sub: string;
473	  email: string;
474	  studentId?: string;
475	};
476	
477	function sign(payload: string): string {
478	  return hmac(payload, cryptoEnv().SESSION_SECRET);
479	}
480	
481	function encode(session: Session): string {
482	  const payload = Buffer.from(JSON.stringify(session)).toString("base64url");
483	  return `${payload}.${sign(payload)}`;
484	}
485	
486	function decode(value: string): Session | null {
487	  const [payload, mac] = value.split(".");
488	  if (!payload || !mac) return null;
489	  if (!safeEqual(mac, sign(payload))) return null;
490	  try {
491	    return JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
492	  } catch {
493	    return null;
494	  }
495	}
496	
497	export async function getSession(): Promise<Session | null> {
498	  const store = await cookies();
499	  const raw = store.get(COOKIE)?.value;
500	  return raw ? decode(raw) : null;
501	}
502	
503	export async function setSession(session: Session): Promise<void> {
504	  const store = await cookies();
505	  store.set(COOKIE, encode(session), {
506	    httpOnly: true,
507	    secure: process.env.NODE_ENV === "production",
508	    sameSite: "lax",
509	    path: "/",
510	    maxAge: MAX_AGE,
511	  });
512	}
513	
514	export async function clearSession(): Promise<void> {
515	  const store = await cookies();
516	  store.delete(COOKIE);
517	}
518	
519	export async function requireSession(): Promise<Session> {
520	  const session = await getSession();
521	  if (!session) throw new Error("UNAUTHENTICATED");
522	  return session;
523	}
