        <div className="space-y-2 border-t border-slate-200 px-3 py-3">''')
s=s.replace('''{open ? "▾" : "▸"}''','''{open ? "Ocultar ▾" : "Detalle ▸"}''')
open(p,'w').write(s)
EOF
