python3 - <<'EOF'
import json,re,glob,os
vals={}
for f in ['.context/t1env.json','.context/t2env.json']:
    for x in json.load(open(f)):
        k,v=x["envVar"]["key"],x["envVar"]["value"]; vals[f"{f[9:11]}:{k}"]=v
for line in open('.env.local'):
    m=re.match(r'\s*([A-Z0-9_]+)\s*=\s*(.+?)\s*$',line)
    if m: vals["local:"+m[1]]=m[2]
public={"APP_BASE_URL","AS_BASE_URL","APP_LOGIN_REALM","NODE_VERSION","LLM_GRPC_TARGET","LLM_GRPC_TLS","LLM_STUDENT_EMAIL","PRE_CLIENT_ID"}
data={f:open(f,encoding='utf8',errors='replace').read() for f in glob.glob('ai-conversations/*.jsonl')}
leaks=0
for name,v in vals.items():
    if name.split(":")[1] in public or len(v)<6: continue
    for f,t in data.items():
        if v in t: print("LEAK", name, os.path.basename(f), t.count(v)); leaks+=1
# DB password part
for name,v in vals.items():
    if name.endswith("DATABASE_URL"):
        pw=re.match(r'postgres(?:ql)?://[^:]+:([^@]+)@',v)
        if pw:
            for f,t in data.items():
                if pw[1] in t: print("LEAK db password", os.path.basename(f)); leaks+=1
pats={"jwt":r'eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}',"gh":r'gh[opsu]_[A-Za-z0-9]{20,}',"rnd":r'rnd_[A-Za-z0-9]{16,}',"sb_secret":r'sb_(secret|publishable)_[A-Za-z0-9_-]{10,}',"pgurl":r'postgres(?:ql)?://[^:\s"\'@]+:(?!\[REDACTED)[^@\s"\']+@',"pk":r'-----BEGIN [A-Z ]*PRIVATE KEY-----',"student":r'[REDACTED]'}
for n,p in pats.items():
    for f,t in data.items():
        c=len(re.findall(p,t))
        if c: print("PATTERN", n, os.path.basename(f), c); leaks+=1
print("total issues:", leaks)
EOF

